.view-choice { display: inline-flex; flex-wrap: wrap; gap: 2px; margin: 0; padding: 3px; border: 1px solid #a3aab5; border-radius: 6px; }
.view-choice legend { position: absolute; width: 1px; height: 1px; padding: 0; overflow: hidden; clip-path: inset(50%); white-space: nowrap; }
.view-choice label { position: relative; cursor: pointer; }
.view-choice input { position: absolute; opacity: 0; width: 1px; height: 1px; }
.view-choice span { display: block; padding: .35rem .65rem; border-radius: 3px; }
.view-choice input:checked + span { background: #173d78; color: white; font-weight: 700; }
.view-choice input:focus-visible + span { outline: 3px solid #3273e8; outline-offset: 2px; }
@media (forced-colors: active) { .view-choice input:checked + span { outline: 2px solid Highlight; } }
